/* AEGIS v7 practical offline manual library; draft instructions, not expert-reviewed. */
(()=>{'use strict';const data=[{"chapter":"Primitive woodworking","title":"Selecting workable wood","purpose":"Choose straight-grained, dry, untreated fallen wood. Avoid rot, splits, fungus, and branches under tension.","steps":["Decide whether the piece will be a handle, peg, mallet or non-load-bearing support; required straightness and thickness depend on the task.","Inspect fallen or salvaged wood for rot, insect tunnels, splits, embedded nails and chemical treatment; reject uncertain or pressure-treated stock for food-contact work.","Follow the grain from end to end; choose the straightest section with the fewest knots near the intended working end.","Check that the diameter leaves enough material after shaping; mark a cut line with pencil or a shallow score.","Brace the stock on a stable surface and cut with the blade path directed away from hands and legs.","Remove loose bark, splinters and sharp edges without cutting deeply across the grain.","Dry damp wood gradually in shade; rapid heating can cause checking and splits.","Test only for its intended light-duty purpose; discard pieces that crack, bend excessively or shed splinters."],"caution":"A knot can deflect a cutting edge; discard split stock.","source":"US Army FM 3-05.70 ch. 12","materials":"Untreated dry wood, gloves, saw, clamp, sandpaper","preflight":"Choose sound untreated stock and keep the workpiece supported.","check":"No deep splits, rot, embedded metal or unstable knots","failure":"Splintering or twisting under light load means discard the stock.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Primitive woodworking","title":"Carving a digging stick","purpose":"Use a sound hardwood branch approximately forearm-to-shoulder length for light soil work.","steps":["Select a straight, sound hardwood branch about forearm-to-shoulder length, thick enough for a secure two-handed grip.","Inspect for cracks, knots, embedded metal and rot; avoid branches that spring back under tension.","Support the branch on a stable surface and cut to length with a suitable saw; keep hands clear of the cutting path.","Smooth the upper grip end into a rounded shape that will not bruise the palm.","Shape the working end into a broad blunt wedge, not a sharp spear-like point.","Remove splinters and test the grip with gloves before use.","Probe only loose garden soil in an area known to be free of buried electrical, gas and water services.","If the end splits or the shaft bends, stop and replace it; do not use it to pry rocks or lift structural loads."],"caution":"Avoid underground utilities and never pry rocks with it.","source":"Original workshop","materials":"Sound untreated wood, suitable hand tools, eye protection","preflight":"Choose sound untreated stock and keep the workpiece supported.","check":"Make a small practice piece before attempting a larger load-bearing project.","failure":"Wear eye protection for cutting and discard cracked parts.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Primitive woodworking","title":"Making a wooden mallet","purpose":"Use a thick, sound hardwood section with a narrower comfortable handle.","steps":["Find a sound hardwood branch with a thicker end and a naturally narrower grip; avoid rotten or split wood.","Inspect the entire piece for cracks, insect damage, knots at the striking face and hidden embedded objects.","Measure a comfortable handle length, and mark a cut line while the wood is supported.","Use a handsaw to cut the branch to length, keeping hands away from the cutting path.","Trim protrusions from the handle without undercutting the thicker striking end.","Sand or smooth the grip and round the striking edges to reduce splintering.","Test only with gentle taps on scrap wood while wearing eye protection.","Inspect for cracks after each test; discard if the head splits or sheds fragments."],"caution":"Wear eye protection; never strike hardened metal.","source":"Original workshop","materials":"Sound hardwood branch, handsaw, sandpaper, eye protection","preflight":"Choose sound untreated stock and keep the workpiece supported.","check":"Head and handle are one sound piece; no splits after gentle test taps","failure":"If the striking end cracks or sheds chips, stop and discard.","sourceStatus":"Reference direction only; exact instructions not independently cross-checked against the named publication."},{"chapter":"Primitive woodworking","title":"Wooden scraper and spatula","purpose":"Make a blunt scraper for mud or residue on nonfragile surfaces.","steps":["Select untreated straight-grained wood suitable for noncritical scraping; avoid painted, pressure-treated or rotten stock.","Sketch a broad rounded working edge and a handle wide enough to hold with wet hands.","Secure the stock on a stable work surface before cutting; keep fingers outside the blade path.","Saw or carve the rough outline in small controlled passes rather than forcing a deep cut.","Round corners and taper the working edge gradually; leave enough thickness to prevent snapping.","Sand the handle and blade face until no splinters remain.","Test on scrap material with light pressure, checking whether the edge flakes or the handle flexes.","For food contact, wash and fully dry between uses; discard if cracked, moldy or difficult to clean."],"caution":"Not automatically food-safe; avoid chemical-treated lumber.","source":"Original workshop","materials":"Sound untreated wood, suitable hand tools, eye protection","preflight":"Choose sound untreated stock and keep the workpiece supported.","check":"Make a small practice piece before attempting a larger load-bearing project.","failure":"Wear eye protection for cutting and discard cracked parts.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Primitive woodworking","title":"Splitting and processing firewood safely","purpose":"Prefer a proper saw and stable chopping surface to improvising sharp tools.","steps":["Confirm splitting is allowed and choose a clear outdoor area with stable footing and no bystanders within tool reach.","Inspect each log for embedded metal, rocks, large knots and irregular grain; avoid striking unknown objects.","Place one manageable log upright on a solid chopping block, never directly against a leg or foot.","Check axe or maul handle security and wear appropriate eye and foot protection.","Stand balanced with feet clear of the intended strike zone and use a controlled motion appropriate to the tool.","Aim along a natural check or straight grain; do not force a blade through a knot with improvised leverage.","Set aside oversized or twisted pieces for a safer tool or professional processing.","Stack split pieces off wet ground with airflow, keeping the pile low and stable; never stack against an exit."],"caution":"Do not cut tensioned limbs or attempt chainsaw work without training.","source":"NPS fire safety","materials":"Sound untreated wood, suitable hand tools, eye protection","preflight":"Choose sound untreated stock and keep the workpiece supported.","check":"Make a small practice piece before attempting a larger load-bearing project.","failure":"Wear eye protection for cutting and discard cracked parts.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Primitive woodworking","title":"Making wooden pegs","purpose":"Use straight small sticks for nonstructural tarp corners and garden markers.","steps":["Select straight-grained untreated wood with no cracks or rotten sections.","Decide peg length and thickness based on soft soil and light tarp loads, not structural anchoring.","Cut blanks longer than the intended buried depth so a short section remains visible for retrieval.","Shape one end to a modest taper using controlled cuts away from your hand.","Round the top so a mallet is less likely to split the grain.","Smooth splinters and inspect for knots that could cause the peg to snap.","Drive into soil at an angle opposing line tension, keeping fingers away from the striking zone.","Pull-test gently and relocate or use a proper manufactured anchor if the peg bends or soil releases."],"caution":"Do not trust homemade pegs as critical storm anchors.","source":"Original workshop","materials":"Sound untreated wood, suitable hand tools, eye protection","preflight":"Choose sound untreated stock and keep the workpiece supported.","check":"Make a small practice piece before attempting a larger load-bearing project.","failure":"Wear eye protection for cutting and discard cracked parts.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Cordage and knots","title":"Reverse-wrap plant cord","purpose":"Make practice twine from known safe flexible fibers.","steps":["Collect only legally permitted non-toxic fibers or use salvaged yarn; avoid unknown irritating plants.","Separate fibers into two roughly equal bundles and remove brittle or rotten sections.","Moisten overly dry fibers slightly if needed to reduce breakage, without soaking the finished line.","Twist the far bundle away from you until it tightens, then cross it over the near bundle toward you.","Repeat the twist-and-cross rhythm while maintaining even tension along both strands.","When fibers shorten, overlap new fibers gradually in alternating positions so the joint does not form one weak spot.","Finish with a secure knot and trim loose ends that could snag.","Test on a light noncritical bundle and inspect joins; never use handmade cord for climbing, rescue or suspending people."],"caution":"Never use for rescue, climbing or human loads.","source":"US Army FM 3-05.70 ch. 12","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Cordage and knots","title":"Three-strand braid","purpose":"Braid salvaged clean strips for bags and light organization.","steps":["Prepare three similar-length clean cords or strips and remove frayed sections.","Anchor one end to a stable stationary object at waist height; never tie to a moving machine.","Lay strands flat in left, center and right positions with equal tension.","Cross the right strand over the center; the former center becomes the right strand.","Cross the left strand over the new center and repeat alternating sides.","Keep each crossing snug but not so tight that one strand bunches or curls.","Tie the finished end and inspect for uneven loops or damaged fibers.","Use only for light organizing tasks; braid strength cannot be assumed for load-bearing use."],"caution":"Uneven tension creates weak spots.","source":"Original workshop","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Cordage and knots","title":"Square lashing","purpose":"Bind two sticks at right angles for a lightweight rack.","steps":["Choose two sound poles that cross approximately at right angles for a light-duty nonstructural rack.","Inspect cord for cuts and poles for splinters, rot or cracks before assembly.","Lay poles on a stable surface and start with a clove hitch on the upright pole close to the crossing.","Wrap the cord around both poles in parallel turns, keeping each turn beside the previous one.","Make several frapping turns between the poles to pull the wraps together.","Finish with a secure hitch and tuck the tail away from walking paths.","Stand the rack up carefully and apply a small gradual test load while watching for slipping.","Do not use this practice joint for overhead loads, climbing, shelters bearing snow or human support."],"caution":"Not suitable for ladders, bridges or overhead supports.","source":"Original workshop","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Cordage and knots","title":"Diagonal lashing","purpose":"Stabilize a loose crossing in a lightweight model frame.","steps":["Use diagonal lashing only where two light-duty poles cross and tend to spring apart.","Inspect both poles and cord; brace the poles so they cannot roll during assembly.","Start with a timber hitch or other secure binding around both poles across one diagonal.","Wrap several turns over one diagonal, keeping the cord flat and evenly tensioned.","Wrap the opposite diagonal with a similar number of turns.","Make frapping turns between the poles to tighten the crossing.","Finish with a secure hitch, then test by gently twisting the assembly by hand.","If the joint slips or the poles split, rebuild or replace; never use for critical structural support."],"caution":"Do not treat practice lashings as engineered structural joints.","source":"Original workshop","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Cordage and knots","title":"Bowline fixed loop","purpose":"Practice a fixed loop using manufactured rope.","steps":["Inspect the rope and select a length for a noncritical practice loop.","Lay the standing part flat and form a small loop with the working end crossing over it.","Pass the working end up through the small loop.","Wrap the working end around the standing part.","Bring the working end back down through the original small loop.","Dress the knot by arranging strands neatly, then pull the standing part and loop to tighten.","Leave an adequate tail and inspect the finished shape before applying a light test pull.","Do not use this tutorial as climbing, rescue or life-safety rigging instruction."],"caution":"Not for life safety without rated gear and instruction.","source":"Original workshop","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Cordage and knots","title":"Clove hitch","purpose":"Use a clove hitch to begin a temporary light-duty lashing.","steps":["Choose a stable post or pole and a cord for a light-duty temporary attachment.","Wrap the working end around the post once, crossing over the standing part.","Make a second wrap in the same direction.","Tuck the working end beneath the second wrap to form two adjacent crossings.","Pull both ends to snug the hitch while keeping the wraps flat.","Apply gentle tension in the expected load direction and check for sliding.","Add a suitable backup if the application requires one, but avoid relying on the hitch for critical loads.","Release and inspect the cord after use; slick cord or changing tension may loosen this hitch."],"caution":"May slip under cyclic or changing load.","source":"Original workshop","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Cordage and knots","title":"Sheet bend","purpose":"Join two ropes of different sizes for noncritical purposes.","steps":["Select two ropes for a light-duty join; form a U-shaped bight in the thicker or less flexible rope.","Pass the working end of the second rope up through the bight from below.","Wrap that end behind both legs of the bight.","Tuck the working end under its own standing part, not under the bight legs.","Dress the knot so both short tails finish on the same side.","Tighten by pulling the standing parts and inspect that the wraps do not cross incorrectly.","Use a doubled sheet bend or different rated joining method when rope sizes differ substantially.","Test only with light noncritical tension; never rely on an improvised knot for lifting people."],"caution":"Can slip on slippery cord; avoid critical use.","source":"Original workshop","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Cordage and knots","title":"Tarp tensioning system","purpose":"Rig a low line with adjustable tension for a temporary rain tarp.","steps":["Inspect reinforced tie-outs and existing cord for abrasion, broken fibers and sharp edges.","Identify the direction wind will pull on the tarp and choose stable anchors away from walkways.","Attach cord to a reinforced tie-out with a secure releasable knot.","Run the cord to the anchor without wrapping around sharp bark or metal corners.","Use an adjustable hitch or appropriate tensioning device to take up slack gradually.","Maintain enough pitch for runoff without stretching seams or tearing grommets.","Tie off loose tails and mark low lines with bright fabric to prevent trips.","Recheck tension after rain, temperature changes or gusts; loosen before fabric or anchors become overloaded."],"caution":"Keep line away from paths and children's reach.","source":"NPS general shelter guidance","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Shelter engineering","title":"A-frame tarp shelter","purpose":"Create a low two-sided rain roof with a tarp and commercial cord.","steps":["Survey a flat elevated patch away from gullies, dead branches, unstable trees, animal trails and runoff channels; identify where rainwater will flow.","Lay the tarp out before tying anything; locate reinforced tie-outs, damaged seams, prevailing wind direction and the intended sleeping footprint.","Select two stable anchors, roughly the desired ridge height; tie a ridgeline with knots you can release with cold hands and keep it away from pedestrian paths.","Drape the tarp evenly over the ridge, leaving enough material on both sides to form steep sloping roof panels.","Stake the windward lower corners first, then the leeward corners; attach cord to reinforced points rather than piercing fabric.","Keep the door end accessible, maintain ventilation and avoid pitching the fabric against sharp rocks or branches.","Lay a separate groundsheet inside without extending it beyond the roof edges, where it would collect runoff.","Build insulation underneath bedding using a closed-cell pad or dry layered materials; a sleeping bag alone compresses under body weight.","Pour a small amount of water over the roof and observe runoff; retension sagging areas and redirect water away from the sleeping zone.","Recheck anchors and roof pitch after wind or rain. Relocate rather than remain under falling limbs, severe winds or flooding."],"caution":"No flame or fuel appliances inside.","source":"US Army FM 3-05.70 shelter chapter","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Shelter engineering","title":"Lean-to tarp shelter","purpose":"Use a single sloping roof for mild-weather rain protection.","steps":["Choose sheltered, higher ground with no dead overhead limbs, flood channel or steep runoff path.","Identify the windward side and position the low edge toward wind-driven rain, while preserving a clear exit.","Run a secure line between two sound anchors at a height appropriate to the tarp width; avoid tying to dead branches.","Attach one long edge of the tarp to the line using reinforced points, distributing tension rather than concentrating it on one grommet.","Pull the opposite edge outward and downward at an angle that sheds water; stake corners securely.","Add side tie-outs or a short side wall if rain can blow through, while maintaining ventilation.","Place the sleeping area behind the low edge, away from drip lines; keep the groundsheet completely under the roof footprint.","Put dry insulating material beneath the sleeping bag and keep spare blankets in a waterproof wrap.","Test roof runoff and anchor stability; adjust pitch if water pools or drips into the bed.","Do not light a stove, heater or fire beneath the tarp; relocate for severe weather or inadequate warmth."],"caution":"Not suitable for extreme wind or severe cold.","source":"US Army FM 3-05.70 shelter chapter","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Shelter engineering","title":"Ground insulation stack","purpose":"Reduce conductive heat loss while resting.","steps":["Choose ground above drainage lines and clear sharp stones, wet debris and hazards without stripping live vegetation unnecessarily.","Spread a waterproof groundsheet or intact tarp under the intended bed, keeping its edges within the roof footprint.","Place a closed-cell foam pad on the groundsheet; if no pad exists, use multiple layers of dry folded material that will not compress completely.","Build thickness under hips, shoulders and torso, where heat loss to ground is greatest.","Place sleeping bag on top; keep the underside dry and avoid putting wet blankets against clothing.","Test by lying down for several minutes; if you can feel cold ground or hard pressure points, add more insulation.","Fold excess groundsheet inward so rain cannot run into the sleeping area.","Air and dry the layers during safe daylight periods; replace saturated material promptly."],"caution":"Seek safe heated shelter in dangerous cold.","source":"CDC cold weather guidance","materials":"Waterproof groundsheet, closed-cell foam pad, dry blankets","preflight":"Check the location and conditions before beginning.","check":"Sleeping surface is dry and protected from conductive ground contact","failure":"If condensation or dampness develops underneath, replace or dry layers.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Shelter engineering","title":"Windbreak without flame","purpose":"Make a low removable wind barrier using a tarp.","steps":["Identify the prevailing wind by observing flags, grass or drifting leaves, and check for unstable trees overhead.","Choose a site outside gullies and flood channels where a barrier will not block the only exit.","Use an existing fence, low wall or securely anchored tarp as the first option rather than cutting live vegetation.","Place the barrier upwind of the sleeping area with enough distance to avoid collapse onto bedding.","Anchor corners to sound posts or stakes, avoiding thin branches and sharp abrasion points.","Keep a clear ventilation path and do not completely seal an occupied space.","Test for flapping, sagging and loose anchors during mild wind; reinforce only with appropriate materials.","Take down or relocate if gusts increase, anchors shift or the barrier threatens to fall."],"caution":"Do not block vents or combustion air.","source":"Original workshop","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Shelter engineering","title":"Rainwater drainage around camp","purpose":"Prevent water from flowing through sleeping area without damaging terrain.","steps":["Walk the site before digging and identify the natural downhill runoff route.","Move tents and sleeping areas out of low ground rather than trying to engineer away a flood risk.","Place gear on raised dry surfaces and keep groundsheet edges inside the shelter footprint.","Remove small loose debris from existing natural runoff paths without diverting water onto neighbors or trails.","Use shallow surface shaping only where lawful and safe; do not dig near roots, buried utilities or unstable slopes.","Direct clean surface runoff away from sleeping and cooking areas without creating erosion.","Watch the first rainfall for pooling and relocate items rather than deepening channels during a storm.","Restore disturbed ground on departure and avoid leaving trip hazards or trenches."],"caution":"Never shelter in streambeds or flood channels.","source":"NPS","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Shelter engineering","title":"Winter warm-room plan","purpose":"Consolidate people into one safe room if heat is limited.","steps":["Choose an interior room with a closing door, minimal exterior windows and a working carbon monoxide alarm.","Check the heating system status and rule out gas, fuel or carbon monoxide hazards before occupying the room.","Bring dry layered clothing, blankets, water, shelf-stable food, medication, flashlights and a battery radio.","Close unused rooms and hang blankets over drafty interior doorways without blocking required ventilation or exits.","Use rugs or foam mats to reduce cold-floor contact and keep bedding off damp concrete.","Monitor indoor temperature, especially for children, older adults and anyone with medical vulnerabilities.","Never use charcoal, a camp stove, gas oven or unvented generator as indoor heat.","If indoor temperature becomes unsafe or symptoms of hypothermia appear, relocate to a verified heated shelter."],"caution":"Never use ovens, charcoal or outdoor heaters indoors.","source":"CDC / Ready.gov","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Fire and cooking","title":"Tinder and kindling selection","purpose":"Understand the difference between fine tinder, pencil-size kindling, and larger fuel.","steps":["Check local fire restrictions and whether a fire is necessary; use safer non-flame options when possible.","Collect dry loose material only where permitted, avoiding unknown treated wood, plastics and toxic plants.","Separate fine tinder from pencil-thin kindling and progressively thicker dry sticks.","Keep a dry reserve in a breathable waterproof-protected pouch so rain does not saturate it.","Crumble a small tinder sample; it should be dry and break apart rather than feel cool and damp.","Split damp sticks only with suitable tools and stable technique; dry inner wood may be more usable.","Build the pile on bare mineral soil or a designated fire ring, away from overhanging vegetation.","Keep water and a shovel ready, supervise continuously and fully extinguish until cold before leaving."],"caution":"No accelerants; never leave fire unattended.","source":"NPS","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Fire and cooking","title":"Fire lay comparison","purpose":"Understand teepee, lean-to, and log-cabin arrangements in a permitted outdoor fire ring.","steps":["Confirm fires are legal and safe under current wind and drought conditions.","Prepare a cleared designated fire area with water and a shovel within reach.","For a teepee lay, loosely lean small kindling over tinder with gaps for airflow.","For a log-cabin lay, cross small sticks in alternating layers around the tinder, leaving an opening.","For a lean-to lay, angle kindling against a larger support stick with the open side away from the wind.","Start with minimal tinder and add fuel gradually; do not use gasoline or other accelerants.","Observe smoke and airflow; excessive smoke often means damp fuel or inadequate oxygen.","Extinguish completely with water, stir and verify cold ashes before departure."],"caution":"Not a method for indoor heating.","source":"US Army FM 3-05.70 fire chapter","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Fire and cooking","title":"Safe outdoor cook station","purpose":"Organize an outdoor cooking zone with adequate separation.","steps":["Choose a lawful outdoor cooking location away from doors, windows, tents, dry brush and overhead branches.","Set a manufactured stove or fire-safe cooking surface on level stable ground; never operate fuel burners in enclosed spaces.","Keep children, pets, loose clothing and combustible supplies outside a clear working perimeter.","Arrange clean food, utensils and water separately from raw meat and dirty equipment.","Place a suitable lid, water and fire extinguisher within reach according to equipment instructions.","Cook food to safe internal temperatures using a food thermometer; appearance alone is unreliable.","Turn off fuel and allow equipment to cool before handling, moving or refueling.","Clean food-contact surfaces, secure waste and check that no embers or heat sources remain."],"caution":"Never use fuel-burning stoves in tents or garages.","source":"CDC CO guidance","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Fire and cooking","title":"Battery light station","purpose":"Avoid fire risk from candles during outages.","steps":["Gather LED flashlights, lanterns, headlamps, charged batteries and any safe USB power banks.","Check battery type, polarity and visible damage; isolate leaking, swollen or overheated cells.","Assign one lamp to the main work area and smaller lights to exits, stairs and sleeping areas.","Place lights on stable surfaces where they cannot fall into water or block a doorway.","Keep one charged handheld light with each household member for movement during outages.","Use low brightness when adequate and switch off unused lights to conserve power.","Store spare batteries in their packaging away from loose metal objects and children.","Test the layout in darkness and note unlit hazards; never substitute candles near bedding or fuel."],"caution":"Do not short batteries or use damaged power packs.","source":"Ready.gov","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no field validation"},{"chapter":"Water","title":"Cloudy-water settling","purpose":"Reduce sediment before disinfection.","steps":["Reject water suspected of fuel, pesticide, industrial chemicals or sewage exposure; settling does not make those hazards safe.","Pour turbid water into a clean transparent container without disturbing the bottom sediment more than necessary.","Leave the container still until heavy particles settle and a clearer layer develops above them.","Slowly decant the clearer upper layer into a second clean vessel without stirring the sediment.","Pass the decanted water through a clean cloth or suitable prefilter to remove remaining visible debris.","Treat the water for microbes using a reliable method appropriate to the situation; filtering through cloth or settling alone does not disinfect.","Store treated water in a clean covered vessel and mark it as treated; keep untreated vessels separate.","If the source is chemically contaminated or treatment cannot be completed, seek a different supply."],"caution":"Sediment removal does not make water safe.","source":"CDC","materials":"Clean covered containers, safe water source, labels","preflight":"Identify microbial versus chemical hazards before choosing treatment.","check":"Prevent recontamination by using clean covered containers.","failure":"When water is suspect and treatment is uncertain, use a verified safe source.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Water","title":"Boiling water for microbes","purpose":"Use boiling for water that may contain germs but not suspected chemicals.","steps":["First assess the source: avoid water that may contain fuel, pesticides, heavy metals, chemical spills or toxic algal blooms; boiling cannot remove these hazards.","If the water is cloudy, let sediment settle and pour the clearer portion through a clean cloth or coffee filter into a pot.","Use a clean heat-safe vessel on a stable cooking surface in a ventilated location; never operate a fuel-burning stove in an enclosed tent or room.","Heat until the entire surface reaches a full rolling boil, not merely small bubbles along the sides.","Maintain the rolling boil for 1 minute, or 3 minutes above 6,500 feet elevation.","Turn off the heat safely and let the water cool in its covered vessel; avoid introducing dirty utensils.","Pour into a clean covered drinking container and label it treated if multiple water containers are in use.","If you cannot safely boil or the source may be chemically polluted, use a different verified source; do not assume boiling solves every contamination problem."],"caution":"Boiling does not remove fuels, metals or pesticides.","source":"CDC","materials":"Heat-safe pot, lid, clean storage vessel, safe heat source","preflight":"Identify microbial versus chemical hazards before choosing treatment.","check":"Full rolling boil for 1 minute, or 3 minutes above 6,500 ft","failure":"If chemical contamination is suspected, do not use boiling as treatment.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Water","title":"Rain catchment","purpose":"Collect rainwater for nonpotable purposes.","steps":["Choose an intact clean tarp or purpose-built collection surface, not roofing treated with unknown coatings.","Secure the collection surface with a stable slope and no sharp folds that trap standing water.","Direct runoff into a clean food-grade vessel; position the opening away from splashing soil and animal waste.","Discard the initial dirty runoff when practical and inspect for insects, debris and bird droppings.","Cover the vessel with a fitted lid or clean mesh to limit contamination and mosquitoes.","Treat collected water for microbes before drinking; rain catchment does not guarantee potable water.","Clean and dry the tarp and vessel between uses; empty stagnant collection points.","Do not drink runoff from surfaces exposed to industrial emissions, chemicals or questionable coatings."],"caution":"Chemical and microbial contamination are possible.","source":"CDC","materials":"Clean covered containers, safe water source, labels","preflight":"Identify microbial versus chemical hazards before choosing treatment.","check":"Prevent recontamination by using clean covered containers.","failure":"When water is suspect and treatment is uncertain, use a verified safe source.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Water","title":"Household water inventory","purpose":"Estimate storage and resupply needs.","steps":["List every person and animal who needs water and note any extra needs due to heat, illness or exertion.","Count sealed potable bottles, filled food-grade containers and known-safe stored water; exclude decorative, toilet and chemical containers.","Record capacity in gallons or liters and mark which supplies are potable versus cleaning-only.","Set a realistic daily drinking and sanitation allowance for the household, recognizing that needs vary substantially.","Calculate days of supply by dividing usable water by the household's daily demand; keep a reserve for uncertainty.","Store containers in cool clean areas away from fuels, pesticides and direct sunlight.","Inspect for leaks, broken seals and expiration or rotation guidance; replace questionable supplies.","Recalculate after each use or refill and post the updated inventory where everyone can find it."],"caution":"Do not ration water dangerously; seek reliable resupply.","source":"Ready.gov","materials":"Clean covered containers, safe water source, labels","preflight":"Identify microbial versus chemical hazards before choosing treatment.","check":"Prevent recontamination by using clean covered containers.","failure":"When water is suspect and treatment is uncertain, use a verified safe source.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Water","title":"Clean storage containers","purpose":"Maintain hygienic stored water.","steps":["Select food-grade containers previously used for food or potable water, not fuel, pesticide or unknown chemicals.","Inspect lids, seals and interior surfaces for cracks, odors, discoloration and trapped residue.","Wash with soap and safe water, reaching threads, handles and lid grooves.","Rinse thoroughly with safe water; sanitize when appropriate using current public-health guidance.","Air-dry on a clean surface without touching the inside with dirty hands.","Label each container by purpose and date, keeping untreated and treated water vessels distinct.","Seal tightly and store away from sunlight, chemicals, pests and heat.","Inspect regularly and discard any container that cannot be cleaned or sealed reliably."],"caution":"Never reuse pesticide or fuel containers.","source":"CDC","materials":"Clean covered containers, safe water source, labels","preflight":"Identify microbial versus chemical hazards before choosing treatment.","check":"Prevent recontamination by using clean covered containers.","failure":"When water is suspect and treatment is uncertain, use a verified safe source.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Food and preservation","title":"No-cook ration planning","purpose":"Plan balanced shelf-stable meals when fuel is unavailable.","steps":["Count household members, pets, dietary restrictions and any foods requiring refrigeration or water to prepare.","List shelf-stable ready-to-eat foods actually available: canned beans, fish, nut butter, crackers, fruit and similar items.","Check labels for calories, protein, allergies and serving sizes rather than counting packages as full meals.","Build a three-day menu using foods that can be opened and eaten without electricity or fuel.","Include a manual can opener, clean utensils, handwashing supplies and safe drinking water.","Pack a small daily allocation for each person while preserving emergency reserves.","Rotate foods by best-use date and replace damaged, swollen or leaking containers.","Review the menu with the household and test one no-cook day to identify gaps before an emergency."],"caution":"Avoid unsafe or damaged cans.","source":"Ready.gov","materials":"Shelf-stable ready-to-eat food, safe water, opener, labels","preflight":"Check the location and conditions before beginning.","check":"Food covers each household member for the intended period","failure":"Repack if allergens, missing calories or expired packaging are found.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Food and preservation","title":"Blackout refrigerator rules","purpose":"Know when perishable foods become unsafe.","steps":["Record when electricity stopped; keep refrigerator and freezer doors closed as much as possible.","Use an appliance thermometer if available rather than judging food safety by smell or taste.","A closed refrigerator generally keeps food cold about 4 hours; a full closed freezer about 48 hours and a half-full freezer about 24 hours.","When power returns, verify temperatures and how long perishable food may have been above 40°F (4°C).","Discard perishable refrigerated foods held above 40°F for 2 hours or longer; when uncertain, throw them out.","Frozen food containing ice crystals or measuring 40°F or below can generally be refrozen or cooked, depending on food type.","Do not taste food to decide if it is safe; photograph and document discarded food for insurance if useful.","Move shelf-stable food to the front of the meal plan until safe refrigeration is restored."],"caution":"Never taste food to test safety.","source":"USDA","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Food and preservation","title":"Dry pantry protection","purpose":"Keep packaged food protected from pests and moisture.","steps":["Inspect storage shelves for leaks, condensation, rodent droppings and direct sunlight.","Move food off the floor and away from exterior walls where moisture can accumulate.","Keep opened dry goods in clean food-grade sealed containers with visible labels.","Group foods by expiration or best-use date, placing older safe items in front.","Inspect packaging for punctures, insects, swelling and contamination before use.","Separate cleaning chemicals, fuels and pesticides from all food and water.","Maintain a simple inventory with quantities and rotation dates.","Discard contaminated or moldy foods; do not attempt to salvage food exposed to floodwater."],"caution":"Discard contaminated or swollen packages.","source":"USDA","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Food and preservation","title":"Wild plant identification safeguards","purpose":"Avoid toxic lookalikes and contamination.","steps":["Start with a locally appropriate printed field guide and identify the exact plant species, not just a similar-looking family.","Examine leaves, stems, growth pattern, habitat and reproductive parts; photograph or sketch multiple features.","Compare the candidate against known toxic look-alikes in the same region and season.","Do not rely on a phone app, single photo, smell, folklore or a generic edibility test as proof of safety.","Check whether the specific part and preparation method are edible; some plants contain toxins in other parts or when raw.","Avoid collecting from sprayed roadsides, industrial sites, contaminated waterways and protected habitats.","If identity or preparation remains uncertain, do not eat the plant; use known packaged food instead.","Keep unfamiliar plants separate from established food and seek poison-control or emergency help after suspected toxic ingestion."],"caution":"Never eat unidentified mushrooms or plants based on AI.","source":"NPS","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Check the location and conditions before beginning.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Navigation and communications","title":"Orienting a paper map","purpose":"Use landmarks and a compass to align a map.","steps":["Locate the map's legend, scale, north arrow, contour interval and date before using it.","Find two or more distinctive landmarks you can see and identify on the map, such as a river bend, road junction or hilltop.","Rotate the map so mapped features align with the actual landscape; use a compass with appropriate declination adjustment if available.","Mark your approximate location in pencil and write the time and weather conditions.","Identify hazards between your location and destination: steep contours, streams, cliffs, roads and private property.","Choose a route using recognizable checkpoints rather than a straight line across unknown terrain.","Estimate distance with the map scale and allow additional time for elevation, vegetation and fatigue.","At each checkpoint, compare what you see against the map and stop to reorient if landmarks no longer match."],"caution":"Map does not confirm route safety.","source":"NPS","materials":"Paper map, pencil, whistle, flashlight","preflight":"Mark your starting point and intended return route.","check":"Use two independent landmarks or references where possible.","failure":"Avoid hazardous shortcuts and share a check-in plan.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Navigation and communications","title":"Shadow-stick direction practice","purpose":"Observe changing shadow position on a clear day.","steps":["Choose a level sunny patch and a straight stick that can stand upright without moving.","Mark the tip of the stick's shadow with a small stone and note the time.","Wait roughly 15–20 minutes while the sun moves and mark the new shadow-tip position.","Draw a straight line from the first mark to the second; this approximates an east–west line.","In the Northern Hemisphere the first mark generally indicates west and the second east, but accuracy is limited.","Draw a perpendicular north–south line as a rough orientation aid.","Cross-check with a map, compass or recognizable terrain; shadows are not precise enough for critical navigation.","Repeat in a clear location if the shadow is diffuse, the stick shifts or terrain slopes."],"caution":"Approximate technique; verify with compass.","source":"US Army FM 3-05.70 navigation","materials":"Paper map, pencil, whistle, flashlight","preflight":"Mark your starting point and intended return route.","check":"Use two independent landmarks or references where possible.","failure":"Avoid hazardous shortcuts and share a check-in plan.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Navigation and communications","title":"Paper route card","purpose":"Prepare no-network navigation notes.","steps":["Write the starting point, destination, date and names of travelers at the top.","Mark planned roads or trails and two or three unmistakable checkpoints along the way.","Record approximate distances, expected travel times and hazards such as streams or steep terrain.","Write a turnaround time and a backup destination if the route becomes blocked.","List emergency contacts and agreed check-in times without exposing sensitive information publicly.","Copy the card or photograph it and leave one copy with a trusted person before departure.","Carry a protected copy with the map and pencil; update the route only when conditions justify it.","If delayed or rerouted, communicate the change when possible rather than allowing rescuers to search an obsolete route."],"caution":"Do not enter closed or flooded roads.","source":"Ready.gov","materials":"Paper map, pencil, whistle, flashlight","preflight":"Mark your starting point and intended return route.","check":"Use two independent landmarks or references where possible.","failure":"Avoid hazardous shortcuts and share a check-in plan.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Navigation and communications","title":"Family radio plan","purpose":"Prepare communications without cellular networks.","steps":["List each radio model, its power source, frequency band and whether a license is required for transmitting.","Agree on primary and backup channels appropriate to the devices and local regulations.","Choose check-in windows and a short message format: name, location, status, needs and next check-in.","Test radios outdoors and inside the home before an emergency; note dead zones and realistic range.","Store spare batteries or an approved charging method and a printed channel card with each radio.","Teach everyone to listen before transmitting and to keep messages brief and unambiguous.","Plan what to do after two missed check-ins; avoid sending people into hazards just to restore contact.","Remember that phone-only browser apps cannot create long-range radio or Bluetooth mesh links without supporting hardware and platform capabilities."],"caution":"Range and reception vary; radios are not guaranteed.","source":"NOAA / Ready.gov","materials":"Paper map, pencil, whistle, flashlight","preflight":"Mark your starting point and intended return route.","check":"Use two independent landmarks or references where possible.","failure":"Avoid hazardous shortcuts and share a check-in plan.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Navigation and communications","title":"Signaling kit","purpose":"Keep low-risk ways to attract rescuers.","steps":["Choose a bright whistle, flashlight, reflective mirror or foil, high-visibility fabric and a written location card.","Keep the kit on your person, not only inside a pack that may be lost or left behind.","Test the whistle and flashlight in a safe setting and verify spare batteries or charging status.","Prepare three short whistle blasts or three visible flashes as a recognizable distress pattern, with pauses between sets.","Select a safe open location visible to searchers without moving into cliffs, traffic or flood paths.","Use bright fabric or a large ground marker that contrasts with its surroundings; avoid obstructing rescue access.","Conserve battery by using a planned signaling rhythm rather than running the light continuously.","If contact is made, share location, number of people, injuries and available supplies; follow responder directions."],"caution":"Do not enter unsafe terrain to signal.","source":"NPS","materials":"Whistle, flashlight, reflective material, spare batteries, bright cloth","preflight":"Mark your starting point and intended return route.","check":"Signals can be produced from a stable safe position without fire","failure":"Never climb hazardous terrain or enter moving water to be more visible.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Wildlife, fishing and trapping","title":"Wildlife trail observation","purpose":"Learn to recognize signs without disturbing animals.","steps":["Choose an observation site away from dens, nests and known animal conflict areas.","Look for prints, scat, rubs and disturbed vegetation without touching bodily waste.","Photograph tracks beside a ruler or familiar object to record scale.","Record substrate, weather, time and direction of travel before signs degrade.","Compare several independent features with a region-specific field guide rather than identifying species from one print.","Avoid approaching animals, feeding them or following tracks into dense cover.","Note repeated routes and habitat features from a safe distance; respect private property and hunting regulations.","Clean footwear and hands after fieldwork and store observations as notes, not as proof of a particular species."],"caution":"Never approach or handle wildlife.","source":"PA Game Commission","materials":"Notebook, binoculars if available, regional wildlife field guide","preflight":"Identify species and non-target risks before any activity.","check":"Sign observations include location, date, habitat and uncertainty","failure":"Do not approach dens, handle scat, or assume one track proves a species.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Wildlife, fishing and trapping","title":"Trapping law and humane standards","purpose":"Understand licensing, species restrictions, seasons and permitted devices.","steps":["Identify your state or local wildlife agency and the landowner whose property would be involved.","Check current licensing, permitted species, seasons, device restrictions and required reporting.","Determine whether any animal may be legally taken in the intended location; do not assume survival removes legal limits.","Review required trap-check intervals, identification tags and humane dispatch rules with official guidance.","Consider nonlethal food sources and fishing where legal before using capture devices.","Never place a device where pets, children, protected wildlife or people could encounter it.","If you cannot meet monitoring, handling or legal requirements, do not set a trap.","Record the current agency contact and regulatory reference offline before heading out."],"caution":"Do not deploy an unverified trap; laws and welfare standards vary.","source":"PA Game Commission","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Identify species and non-target risks before any activity.","check":"Keep distance from wildlife and protect against contamination.","failure":"Avoid untested improvised capture devices and check local rules.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Wildlife, fishing and trapping","title":"Non-operational snare demonstration","purpose":"Study the components of a historical snare without building a working capture device.","steps":["Use soft yarn or string and a smooth cardboard tube on a tabletop; do not place any loop outdoors.","Form a loose sliding loop solely to observe how friction changes as cord moves.","Pass the cord through the loop and note how tension reduces its diameter.","Compare thin and thick practice cords and observe differences in sliding and binding.","Mark the sample clearly as a classroom model, not a capture device.","Keep the demonstration away from children and pets; never tighten a loop around a body part.","Untie and dismantle the model immediately after practice.","For real-world wildlife needs, consult current wildlife-agency rules and humane professionals rather than deploying a homemade device."],"caution":"This is a study guide, not an operational animal trap.","source":"US Army FM 3-05.70 ch. 8","materials":"Paper, pencil, lightweight string for a nonfunctional tabletop display","preflight":"Identify species and non-target risks before any activity.","check":"Model cannot tighten around an animal, person or pet","failure":"Never deploy practice loops in wildlife areas or near pets.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Wildlife, fishing and trapping","title":"Non-operational deadfall model","purpose":"Explore the geometry of a historical deadfall safely.","steps":["Use a light empty cardboard box, foam block and blunt craft sticks on a clear tabletop.","Set the box upright and demonstrate its center of mass without adding heavy objects.","Place the foam block beneath one edge to model a supported object.","Gently remove the foam and observe how the box settles under its own negligible weight.","Discuss why a real falling weight creates crushing hazards and cannot be treated as a toy.","Keep fingers out of the closing edge even in this light demonstration.","Dismantle the model and store all pieces after use.","Never substitute rocks, logs or heavy loads for the model; this is not a working animal trap."],"caution":"Never use a falling weight or live trigger in a practice model.","source":"US Army FM 3-05.70 ch. 8","materials":"Lightweight foam pieces, fixed supports, paper labels","preflight":"Identify species and non-target risks before any activity.","check":"Model cannot fall or release stored energy","failure":"Never use a heavy falling weight or live trigger.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Wildlife, fishing and trapping","title":"Fishing regulations and equipment","purpose":"Plan lawful food fishing with safe gear.","steps":["Identify a safe bank or shoreline and check water hazards, weather and consumption advisories.","Learn the likely local fish species using a regional guide; avoid consuming unidentified catches.","Choose a line, hook and float or sinker sized for the species and conditions.","Tie and inspect the hook knot; pull-test the connection with controlled tension.","Carry pliers and a safe container or cooler for handling retained fish.","Keep hooks clear of other people, children and pets when casting or handling.","Follow applicable harvest limits and humane handling practices.","If keeping fish, chill promptly and avoid contaminated waters."],"caution":"Do not eat fish from contaminated waters.","source":"PA Fish and Boat Commission","materials":"Local species guide, line, hook, bait, pliers, safe footwear","preflight":"Identify species and non-target risks before any activity.","check":"Species and water are identified; tackle is secured; fish advisory checked","failure":"If a species is unidentified or a consumption advisory applies, do not eat it.","sourceStatus":"Reference direction only; exact instructions not independently cross-checked against the named publication."},{"chapter":"Wildlife, fishing and trapping","title":"Track and sign journal","purpose":"Build wildlife knowledge without capture.","steps":["Create columns for date, time, location, weather, substrate and observation type.","Photograph or sketch the sign before approaching closely enough to disturb it.","Record approximate dimensions and direction of prints using a scale reference.","Describe what is actually visible before making a species guess.","Look for multiple corroborating signs such as gait pattern, habitat and repeated tracks.","Mark confidence as high, medium or low and note possible look-alike species.","Avoid handling scat, carcasses or unknown biological material.","Compare entries over time, but do not infer population or hunting success from a single track."],"caution":"Tracks rarely prove species alone.","source":"NPS","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Identify species and non-target risks before any activity.","check":"Keep distance from wildlife and protect against contamination.","failure":"Avoid untested improvised capture devices and check local rules.","sourceStatus":"Expanded original procedural draft; no independent field validation"},{"chapter":"Household survival","title":"Oil boiler outage response","purpose":"Plan around electrically dependent boiler controls and pumps.","steps":["Confirm whether the issue is an area-wide power outage or a boiler-specific fault; check for unusual smells, smoke or water leaks from a safe distance.","If you smell fuel oil, see active leakage or suspect carbon monoxide, leave the area and contact qualified help; do not attempt repairs.","Check thermostat setting and whether the home has electrical power without opening energized panels.","Do not repeatedly press the burner reset button; repeated resets can accumulate unburned fuel.","Keep access to the boiler clear and do not cover vents, flues, relief valves or controls.","Concentrate the household in a safe warm room, wear layered clothing and close unused interior doors while maintaining required ventilation.","Protect vulnerable plumbing by monitoring indoor temperature and seeking licensed guidance for winterization if freezing is possible.","Use only manufacturer-approved backup-power arrangements installed by qualified professionals; never backfeed house wiring or run a generator indoors."],"caution":"Never bypass controls or backfeed circuits.","source":"Ready.gov / manufacturer","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Assign a household owner and record a completion date.","check":"Test supplies in daylight under normal conditions first.","failure":"Never bypass electrical, fuel, heating or sanitation safety controls.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Household survival","title":"Generator carbon monoxide safety","purpose":"Keep exhaust far from occupied spaces.","steps":["Read the generator manual and check that the unit is rated for the intended electrical loads.","Position the generator outdoors at least 20 feet from doors, windows and vents, with exhaust directed away from the building.","Never place it in a garage, basement, porch, shed or near an open window, even with doors open.","Install working battery-backed carbon monoxide alarms near sleeping areas and on each level of the home.","Keep the generator dry under a purpose-built open-sided canopy without enclosing exhaust or blocking cooling.","Connect appliances directly using correctly rated outdoor extension cords, or use a professionally installed transfer switch.","Never connect a generator to a wall outlet or improvise a connection to the home's electrical panel.","Shut down and cool before refueling; store fuel safely away from living spaces and ignition sources.","If a CO alarm sounds or anyone develops headache, nausea or dizziness, move everyone outdoors and call emergency services."],"caution":"Never run generators in garage, basement or near vents.","source":"CDC","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Assign a household owner and record a completion date.","check":"Test supplies in daylight under normal conditions first.","failure":"Never bypass electrical, fuel, heating or sanitation safety controls.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Household survival","title":"Emergency sanitation station","purpose":"Maintain hygiene during water outages.","steps":["Choose a private accessible location away from food preparation and potable-water storage.","Set out a lined waste container with a tight-fitting lid and separate bags for used wipes and hygiene supplies.","Keep hand soap, clean water and a designated wash basin next to the station; sanitizer is a fallback when hands are not visibly dirty.","Label clean and contaminated supplies so household members do not mix them.","If flushing is unavailable, use a sturdy seat or supported container designed for the task; avoid unstable improvised supports.","Seal waste bags before they become too heavy and store them away from children, pets, insects and water sources.","Wash hands thoroughly after every use and before handling food.","Follow local emergency public-health guidance for final waste disposal; do not bury waste near wells or surface water."],"caution":"Keep waste away from drinking water and food.","source":"CDC","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Assign a household owner and record a completion date.","check":"Test supplies in daylight under normal conditions first.","failure":"Never bypass electrical, fuel, heating or sanitation safety controls.","sourceStatus":"Expanded original procedural draft; verify against current primary guidance before relying on it"},{"chapter":"Household survival","title":"Household supply rotation","purpose":"Prevent expired or missing supplies.","steps":["Divide supplies into drinking water, food, medical, lighting, hygiene and communication categories.","Count items and note the package size, expiration or best-use date and storage location.","Inspect containers for leaks, swelling, corrosion, damage or missing labels.","Put oldest safe items at the front and move newer replacements behind them.","Schedule a monthly quick check and a deeper seasonal inspection.","Test batteries and radio power sources according to manufacturer instructions.","Record consumed, discarded and replenished items in a paper or offline inventory.","Review household needs after changes in membership, medications, pets or season."],"caution":"Adjust for children, pets and medical needs.","source":"Ready.gov","materials":"Basic supplies appropriate to this activity, protective equipment, notebook","preflight":"Assign a household owner and record a completion date.","check":"Test supplies in daylight under normal conditions first.","failure":"Never bypass electrical, fuel, heating or sanitation safety controls.","sourceStatus":"Expanded original procedural draft; no independent field validation"}];const root=document.getElementById('library-v7');if(!root)return;const q=document.getElementById('v7-search'),cat=document.getElementById('v7-category'),list=document.getElementById('v7-list'),count=document.getElementById('v7-count');const el=(t,c,v)=>{const n=document.createElement(t);if(c)n.className=c;if(v!==undefined)n.textContent=v;return n};[...new Set(data.map(x=>x.chapter))].forEach(c=>{const o=el('option','',c);o.value=c;cat.append(o)});function render(){const term=q.value.toLowerCase().trim();const filtered=data.filter(x=>(!cat.value||cat.value===x.chapter)&&(!term||[x.title,x.chapter,x.purpose,x.caution,...x.steps].join(' ').toLowerCase().includes(term)));count.textContent=filtered.length+' of '+data.length+' procedures · '+new Set(data.map(x=>x.chapter)).size+' subjects';list.replaceChildren();for(const x of filtered){const d=el('details','wild-guide'),s=el('summary','',x.title);s.prepend(el('span','wild-guide-tag',x.chapter));d.append(s);const b=el('div','wild-guide-body');b.append(el('p','',x.purpose),el('h4','','Procedure'));const ol=el('ol','');x.steps.forEach(v=>ol.append(el('li','',v)));b.append(ol,el('h4','','Materials and preparation'),el('p','',x.materials),el('p','',x.preflight),el('h4','','Completion check'),el('p','',x.check),el('h4','','If something goes wrong'),el('p','',x.failure),el('h4','','Safety / limitations'),el('p','wild-guide-warning',x.caution),el('p','muted','Source direction: '+x.source+' · '+x.sourceStatus));d.append(b);list.append(d)}if(!filtered.length)list.append(el('p','muted','No matching procedures. Try a different term.'))}q.addEventListener('input',render);cat.addEventListener('change',render);render()})();